{"cmd": "cd /testbed && python3 - <<'EOF'
import json, fnmatch, re

rules = []
for raw in open(".github/CODEOWNERS"):
    line = raw.rstrip("\n")
    if not line.strip() or line.lstrip().startswith("#"):
        continue
    parts = line.split()
    rules.append((parts[0], parts[1:]))
    assert len(parts) == 2, f"unexpected tokens (trailing comment?): {line!r}"

mapping = json.load(open("examples/approved-owners.json"))["owners"]

def owners_for(path):
    last = None
    for pat, own in rules:
        p = pat.lstrip("/")
        target = path.lstrip("/")
        if p.endswith("/"):
            if target.startswith(p) or fnmatch.fnmatch("/" + target, pat + "*"):
                last = own
        elif fnmatch.fnmatch(target, p) or target == p:
            last = own
    return last

print(f"{'pattern':<12} {'expected':<28} {'effective':<28} ok")
allok = True
for pat, expected in mapping.items():
    sample = {
        "/.github/": ".github/workflows/ci.yml",
        "/deploy/": "deploy/deploy.sh",
        "/src/auth/": "src/auth/session.py",
        "/docs/": "docs/architecture.md",
    }[pat]
    eff = owners_for(sample)
    ok = eff == [expected]
    allok &= ok
    print(f"{pat:<12} {expected:<28} {str(eff):<28} {ok}")

for sample in ["src/api/routes.py", "README.md", "SECURITY.md"]:
    print("unmapped:", sample, "->", owners_for(sample))

quals = json.load(open("examples/approved-owners.json"))["qualifications"]
for team, q in quals.items():
    print("qualification present in file:", team, any(team in open(".github/CODEOWNERS").read() for _ in [0]), "|", q)
print("ALL MAPPING ENTRIES APPLIED:", allok)
EOF"}
